from typing import Any, Optional, cast

from lxml import etree
from requests import Session
from requests.auth import HTTPBasicAuth
from zeep import Client
from zeep.plugins import HistoryPlugin
from zeep.proxy import ServiceProxy
from zeep.transports import Transport
from zeep.wsse.username import UsernameToken


class SoapAdapter:

    def __init__(self, wsdl_url: str, username: str, password: str) -> None:
        self.wsdl_url = wsdl_url
        self.username = username
        self.password = password
        self.session = Session()
        self.history = HistoryPlugin()
        self._client: Optional[Client] = None

    @property
    def client(self) -> Client:
        """
        Initialize SOAP client
        """
        if not self._client:
            self._prepare_session()
            transport = Transport(session=self.session)
            plugins = [self.history]
            wsse = UsernameToken(username=self.username,
                                 password=self.password)
            self._client = Client(self.wsdl_url, transport=transport,
                                  plugins=plugins, wsse=wsse)
        return cast(Client, self._client)

    def _prepare_session(self) -> None:
        self.session.verify = False
        self.session.auth = HTTPBasicAuth(self.username, self.password)

    @property
    def service(self) -> ServiceProxy:
        """
        :return: service object with available SOAP methods
        :rtype: zeep.proxy.ServiceProxy
        """
        return self.client.service

    def last_request(self, as_string: bool = True) -> Any:
        """
        :param bool as_string: returns string if True
        :return: last SOAP request
        :rtype: string | lxml.etree.Element
        """
        envelope = self.history.last_sent['envelope']
        return self._xml_to_string(envelope) if as_string else envelope

    def last_response(self, as_string: bool = True) -> Any:
        """
        :param bool as_string: returns string if True
        :return: last SOAP response
        :rtype: string | lxml.etree.Element
        """
        envelope = self.history.last_received['envelope']  # type: ignore[index]
        return self._xml_to_string(envelope) if as_string else envelope

    @staticmethod
    def _xml_to_string(xml):
        return etree.tostring(xml, pretty_print=True)
